  virtual function void write(alu_transaction trans);
    bit [7:0] expected_y;
    bit [3:0] expected_flags;
    bit [8:0] sum;
    bit [8:0] diff;

    expected_y     = 8'h00;
    expected_flags = 4'b0000;
    sum            = 9'h000;
    diff           = 9'h000;

    case (trans.opcode)
      3'b000: begin // ADD
        sum = {1'b0, trans.a} + {1'b0, trans.b};
        expected_y = sum[7:0];
        expected_flags[1] = sum[8]; // carry
        expected_flags[3] =
          (~trans.a[7] & ~trans.b[7] & expected_y[7]) |
          ( trans.a[7] &  trans.b[7] & ~expected_y[7]); // overflow
      end

      3'b001: begin // SUB
        diff = {1'b0, trans.a} + {1'b0, ~trans.b} + 9'b1;
        expected_y = diff[7:0];
        expected_flags[1] = diff[8]; // carry/no-borrow
        expected_flags[3] =
          ( trans.a[7] & ~trans.b[7] & ~expected_y[7]) |
          (~trans.a[7] &  trans.b[7] &  expected_y[7]); // overflow
      end

      3'b010: begin // AND
        expected_y = trans.a & trans.b;
      end

      3'b011: begin // OR
        expected_y = trans.a | trans.b;
      end

      3'b100: begin // XOR
        expected_y = trans.a ^ trans.b;
      end

      3'b101: begin // NOT
        expected_y = ~trans.a;
      end

      3'b110: begin // SHL
        expected_y = trans.a << 1;
        expected_flags[1] = trans.a[7]; // carry
      end

      3'b111: begin // SHR
        expected_y = trans.a >> 1;
        expected_flags[1] = trans.a[0]; // carry
      end

      default: begin
        expected_y = 8'h00;
      end
    endcase

    // Common flags for all operations
    expected_flags[0] = expected_y[7];        // sign
    expected_flags[2] = (expected_y == 8'h00); // zero

    if (trans.y !== expected_y) begin
      $error("Mismatch! a=%0d b=%0d opcode=%0b | Expected Y: %0d, Got: %0d",
             trans.a, trans.b, trans.opcode, expected_y, trans.y);
